-- Local demo data only. The referenced PDFs are generated by
-- generate-demo-advance-documents.py and are not legal accounting evidence.
BEGIN;

WITH demo_docs(request_code, file_name, public_id, size_bytes) AS (
    VALUES
        ('REQ-IT-0926-075', 'REQ-IT-0926-075-du-toan-hoi-thao.pdf', 'ifms-demo/REQ-IT-0926-075-du-toan-hoi-thao.pdf', 83932),
        ('REQ-IT-1126-115', 'REQ-IT-1126-115-du-toan-thue-thiet-bi.pdf', 'ifms-demo/REQ-IT-1126-115-du-toan-thue-thiet-bi.pdf', 83914),
        ('REQ-IT-1126-116', 'REQ-IT-1126-116-du-toan-huong-dan.pdf', 'ifms-demo/REQ-IT-1126-116-du-toan-huong-dan.pdf', 84069),
        ('REQ-FIN-1126-117', 'REQ-FIN-1126-117-du-toan-phu-kien.pdf', 'ifms-demo/REQ-FIN-1126-117-du-toan-phu-kien.pdf', 84016),
        ('REQ-IT-1126-118', 'REQ-IT-1126-118-du-toan-di-chuyen.pdf', 'ifms-demo/REQ-IT-1126-118-du-toan-di-chuyen.pdf', 83973),
        ('REQ-IT-1126-119', 'REQ-IT-1126-119-du-toan-thiet-bi-kiem-thu.pdf', 'ifms-demo/REQ-IT-1126-119-du-toan-thiet-bi-kiem-thu.pdf', 83896),
        ('REQ-FIN-1126-120', 'REQ-FIN-1126-120-du-toan-dao-tao.pdf', 'ifms-demo/REQ-FIN-1126-120-du-toan-dao-tao.pdf', 84186),
        ('REQ-IT-0926-069', 'REQ-IT-0926-069-bang-ke-quyet-toan.pdf', 'ifms-demo/REQ-IT-0926-069-bang-ke-quyet-toan.pdf', 83232)
), resolved AS (
    SELECT r.id AS request_id, r.requester_id, d.file_name, d.public_id, d.size_bytes
    FROM demo_docs d
    JOIN requests r ON r.request_code = d.request_code
    WHERE r.status = 'APPROVED_BY_TEAM_LEADER'
), stored AS (
    INSERT INTO file_storages(
        created_at, updated_at, created_by, updated_by,
        file_name, cloudinary_public_id, url, file_type, size
    )
    SELECT now(), now(), requester_id, requester_id,
           file_name, public_id, '/demo-documents/' || file_name,
           'application/pdf', size_bytes
    FROM resolved
    ON CONFLICT (cloudinary_public_id) DO UPDATE SET
        url = EXCLUDED.url,
        file_type = EXCLUDED.file_type,
        size = EXCLUDED.size
    RETURNING id, cloudinary_public_id
)
INSERT INTO request_attachments(file_id, request_id)
SELECT s.id, r.request_id
FROM stored s
JOIN resolved r ON r.public_id = s.cloudinary_public_id
ON CONFLICT DO NOTHING;

COMMIT;
